vector<int> read_point(int k) {
    vector<int> point(k);
    for (int i = 0; i < k; i++) {
        cin >> point[i];
    }
    return point;
}

void solve() {
    int n, k;
    cin >> n >> k;

    vector<vector<int>> points;
    for (int i = 0; i < n; i++) {
        points.push_back(read_point(k));
    }

    kd_tree tree(points, k);

    int q;
    cin >> q;
    cout << fixed << setprecision(3);

    for (int i = 0; i < q; i++) {
        cout << tree.closest_point(read_point(k)) << "\n";
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();

    return 0;
}

